index 6a802bd74a7..bcb58e53e00 100644
--- a/mail/components/storybook/stories/widgets.stories.mjs
+++ b/mail/components/storybook/stories/widgets.stories.mjs
@@ -5,6 +5,7 @@
 import { html } from "lit";
 import "mail/themes/shared/mail/variables.css";
 import "mail/themes/shared/mail/widgets.css";
+import "mail/themes/shared/mail/spacings.css";
 import "mail/themes/shared/mail/icons.css";

 export default {
@@ -146,3 +147,30 @@ export const Select = () => html`
     <option value="B">Another one</option>
   </select>
 `;
+
+export const Badge = () => html`
+  <p>
+    <span class="badge" role="presentation">Recommended</span>
+    <span class="badge inverted" role="presentation">Recommended</span><br />
+    <span class="badge beta" role="presentation">Beta</span>
+    <span class="badge beta inverted" role="presentation">Beta</span><br />
+    <span class="badge experimental" role="presentation">Experimental</span>
+    <span class="badge experimental inverted" role="presentation"
+      >Experimental</span
+    ><br />
+    <span class="badge alpha" role="presentation">Alpha</span>
+    <span class="badge alpha inverted" role="presentation">Alpha</span>
+  </p>
+  <p style="background: var(--color-surface-base-dark); color-scheme: dark">
+    <span class="badge" role="presentation">Recommended</span>
+    <span class="badge inverted" role="presentation">Recommended</span><br />
+    <span class="badge beta" role="presentation">Beta</span>
+    <span class="badge beta inverted" role="presentation">Beta</span><br />
+    <span class="badge experimental" role="presentation">Experimental</span>
+    <span class="badge experimental inverted" role="presentation"
+      >Experimental</span
+    ><br />
+    <span class="badge alpha" role="presentation">Alpha</span>
+    <span class="badge alpha inverted" role="presentation">Alpha</span>
+  </p>
+`;
diff --git a/mail/themes/shared/mail/widgets.css b/mail/themes/shared/mail/widgets.css
index fce5feed58b..a1b55bf3904 100644
--- a/mail/themes/shared/mail/widgets.css
+++ b/mail/themes/shared/mail/widgets.css
@@ -683,3 +683,56 @@
   padding: 0;
   position: absolute;
 }
+
+.badge {
+  text-transform: uppercase;
+  font-size: 0.77rem;
+  font-weight: bold;
+  padding: var(--space-step) calc(2 * var(--space-step));
+  border-radius: var(--space-step);
+  text-align: center;
+  display: inline-block;
+
+  color: var(--color-surface-base);
+  background-color: var(--color-primary-default);
+
+  &.beta {
+    color: var(--color-secondary-soft);
+    background-color: var(--color-secondary-default);
+  }
+
+  &.experimental {
+    color: light-dark(var(--color-text-warning-light), var(--color-warning-soft-dark));
+    background-color: light-dark(var(--color-warning-default-light), var(--color-warning-pressed-dark));
+  }
+
+  &.alpha {
+    color: var(--color-surface-base);
+    background-color: var(--color-critical-default);
+  }
+
+  &.inverted {
+    color: var(--color-primary-hover);
+    background-color: var(--color-primary-soft);
+
+    &.beta {
+      color: var(--color-secondary-pressed);
+      background-color: var(--color-secondary-soft);
+    }
+
+    &.experimental {
+      color: var(--color-text-warning);
+      background-color: var(--color-warning-soft);
+    }
+
+    &.alpha {
+      color: light-dark(var(--color-critical-pressed-light), var(--color-critical-default-dark));
+      background-color: var(--color-critical-soft);
+    }
+  }
+
+  @media (prefers-contrast) {
+    color: ButtonText;
+    background-color: ButtonFace;
+  }
+}
